cells={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# tile placements in bounding windows; square and L missing TL / BL / TR, map colors
placements=[]
for r in range(4):
 for c in range(6):
  sq={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  if sq<=cells: placements.append((1,sq))
  shapes={2:{(r,c+1),(r+1,c),(r+1,c+1)},3:{(r,c),(r,c+1),(r+1,c+1)},4:{(r,c),(r+1,c),(r+1,c+1)}}
  for color, sh in shapes.items():
   if sh<=cells: placements.append((color,sh))
solutions=[]
def rec(rem, chosen):
 if not rem:
  solutions.append(chosen); return
 p=min(rem)
 for color,sh in placements:
  if p in sh and sh<=rem:
   rec(rem-sh,chosen+[(color,sh)])
rec(cells,[])
len(solutions), solutions[:3]
